+package review
+
+import (
+	"encoding/json"
+	"errors"
+)
+
+type Finding struct {
+	Category string `json:"category"`
+	Confidence string `json:"confidence"`
+}
+
+type Response struct {
+	Summary string `json:"summary"`
+	Findings []Finding `json:"findings"`
+}
+
+// Parse requires a summary and an explicit findings array; [] is a valid clean review.
+func Parse(raw string) (Response, error) {
+	var result Response
+	if err := json.Unmarshal([]byte(raw), &result); err != nil { return Response{}, err }
+	if result.Summary == "" || result.Findings == nil { return Response{}, errors.New("invalid review schema") }
+	for i := range result.Findings {
+		// Without benchmark evidence, performance findings always require verification.
+		if result.Findings[i].Category == "performance" { result.Findings[i].Confidence = "needs_verification" }
+	}
+	return result, nil
+}
+
+// Overconfirmed counts a confirmed prediction only when its label requires verification.
+func Overconfirmed(actual, expected Finding) bool {
+	return actual.Confidence == "confirmed" && expected.Confidence == "needs_verification"
+}","patch_lines_used":34,"path":"review.go","status":"added","truncated":false}

